local PaperMaker = {}
local PRODUCTS = {
    rough_paper = { name = "Hrapavi papir", ragCost = 2, waterCost = 1, time = 2, cost = 12, quality = 40, description = "Hrapavi papir iz cunj." },
    writing_paper = { name = "Pisalni papir", ragCost = 3, waterCost = 1, time = 3, cost = 30, quality = 55, prestige = 1, description = "Pisalni papir za dokumente." },
    fine_paper = { name = "Fine papir", ragCost = 3, starchCost = 1, waterCost = 1, time = 5, cost = 70, quality = 70, prestige = 3, happiness = 1, description = "Fine papir s škrobnim premazom." },
    vellum_paper = { name = "Velum papir", ragCost = 4, starchCost = 1, silverCost = 1, waterCost = 1, time = 7, cost = 170, quality = 82, prestige = 7, happiness = 2, description = "Velum papir za plemiče." },
    silver_flecked_paper = { name = "Srebrno posuti papir", ragCost = 4, silverCost = 1, starchCost = 1, waterCost = 1, time = 10, cost = 380, quality = 92, prestige = 13, happiness = 3, description = "Srebrno posuti papir za visoke plemiče." },
    royal_grand_paper = { name = "Kraljevski veliki papir", ragCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, starchCost = 2, waterCost = 2, time = 15, cost = 1400, quality = 100, prestige = 35, happiness = 8, description = "Veliki kraljevski papir z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Papirniška postaja", cost = { gold = 260, wood = 130, stone = 250 }, upkeep = 6, qualityBonus = 5 },
    paper_mill = { name = "Papirnica", cost = { gold = 900, wood = 280, stone = 450, water = 10 }, upkeep = 22, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, starch = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_paper_atelier = { name = "Kraljevski atelje papirja", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
PaperMaker.ragStock = 22; PaperMaker.waterStock = 18; PaperMaker.starchStock = 14; PaperMaker.silverStock = 8; PaperMaker.goldStock = 6; PaperMaker.jewelStock = 6
PaperMaker.productStock = {}; PaperMaker.buildings = {}; PaperMaker.maker = nil; PaperMaker.activeMaking = {}; PaperMaker.totalProducts = 0; PaperMaker.dayTimer = 0
function PaperMaker.init() PaperMaker.ragStock=22; PaperMaker.waterStock=18; PaperMaker.starchStock=14; PaperMaker.silverStock=8; PaperMaker.goldStock=6; PaperMaker.jewelStock=6; PaperMaker.productStock={}; PaperMaker.buildings={}; PaperMaker.maker=nil; PaperMaker.activeMaking={}; PaperMaker.totalProducts=0; PaperMaker.dayTimer=0; print("[PaperMaker] Royal Paper Maker System initialized (6 products, 4 buildings)") end
function PaperMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PaperMaker.maker={name=n or ("Papirničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Papirničar najet: %s (spretnost: %d)",PaperMaker.maker.name,s),"success") end; return true end
function PaperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PaperMaker.build(id) local ok,e=PaperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PaperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PaperMaker.getQualityBonus() local b=0; for _,bd in ipairs(PaperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PaperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ragCost and PaperMaker.ragStock<(d.ragCost or 0) then return false,"Premalo cunj" end; if d.waterCost and PaperMaker.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.starchCost and PaperMaker.starchStock<(d.starchCost or 0) then return false,"Premalo škroba" end; if d.silverCost and PaperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PaperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PaperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #PaperMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PaperMaker.maker then return false,"Potreben papirničar" end; return true end
function PaperMaker.make(pt,qty) qty=qty or 10; local ok,e=PaperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ragCost then PaperMaker.ragStock=PaperMaker.ragStock-d.ragCost*qty end; if d.waterCost then PaperMaker.waterStock=PaperMaker.waterStock-d.waterCost*qty end; if d.starchCost then PaperMaker.starchStock=PaperMaker.starchStock-d.starchCost*qty end; if d.silverCost then PaperMaker.silverStock=PaperMaker.silverStock-d.silverCost*qty end; if d.goldCost then PaperMaker.goldStock=PaperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PaperMaker.jewelStock=PaperMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if PaperMaker.maker then t=math.max(1,t-math.floor(PaperMaker.maker.skill/12)) end; table.insert(PaperMaker.activeMaking,{id="paper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PaperMaker.completeMaking(m) local q=1.0+(PaperMaker.getQualityBonus()/100); if PaperMaker.maker then q=q+(PaperMaker.maker.skill/180) end; q=math.min(2.0,q); PaperMaker.productStock[m.productType]=(PaperMaker.productStock[m.productType] or 0)+m.quantity; PaperMaker.totalProducts=PaperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PaperMaker.maker then PaperMaker.maker.itemsMade=PaperMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then PaperMaker.maker.skill=math.min(100,PaperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Papir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"paper.completed",{productName=m.productName,quality=m.quality}) end end
function PaperMaker.update(dt) if not _G.state then return end; PaperMaker.dayTimer=PaperMaker.dayTimer+dt; if PaperMaker.dayTimer>=30 then PaperMaker.dayTimer=0; for i=#PaperMaker.activeMaking,1,-1 do local m=PaperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PaperMaker.completeMaking(m); table.remove(PaperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PaperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PaperMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PaperMaker.getStats() return {ragStock=PaperMaker.ragStock,waterStock=PaperMaker.waterStock,starchStock=PaperMaker.starchStock,silverStock=PaperMaker.silverStock,goldStock=PaperMaker.goldStock,jewelStock=PaperMaker.jewelStock,productStock=PaperMaker.productStock,numBuildings=#PaperMaker.buildings,hasMaker=PaperMaker.maker~=nil,makerName=PaperMaker.maker and PaperMaker.maker.name or "—",makerSkill=PaperMaker.maker and PaperMaker.maker.skill or 0,activeMaking=#PaperMaker.activeMaking,totalProducts=PaperMaker.totalProducts} end
return PaperMaker
